export function demo(id='servly'){const t=templates.find(t=>t.id===id)||templates[0];return {name:t.name,appName:'',appIcon:'',template:t.id,lang:'fa',tagline:t.headline,description:t.description,about:'ما به کیفیت، دقت و تجربه‌ای خوشایند باور داریم. این متن نمونه را با داستان واقعی کسب‌وکارت جایگزین کن.',color:t.color,background:t.bg,ink:t.ink,logo:'',cover:demoMedia[({servly:'clean',eduboss:'art',artstore:'room',sport:'swim'})[t.id]],phone:'',email:'',address:'',website:'',instagram:'',telegram:'',whatsapp:'',slug:'',items:t.items.map((v,i)=>({id:String(i+1),title:v[0],description:v[1],price:v[2],art:v[3],image:demoMedia[({servly:['clean','tools','room'],eduboss:['art','design','camera'],artstore:['bag','plant','mug'],sport:['shoes','shirt','swim']})[t.id][i]],category:t.categories[i+1]})),gallery:[],plans:[{title:'پایه',price:'تماس بگیرید',features:'معرفی خدمات\nمشاوره اولیه'},{title:'حرفه‌ای',price:'تماس بگیرید',features:'خدمات کامل\nپشتیبانی اختصاصی'},{title:'ویژه',price:'تماس بگیرید',features:'راهکار سفارشی\nهمراهی مستمر'}],reviews:[],sections:{about:true,gallery:true,plans:false,reviews:false},isDemo:true};}
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const safeURL=(s,type='web')=>{s=String(s||'').trim();if(type==='image')return /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s)?s:'';try {const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
export function normalize(c={}){const t=templates.find(t=>t.id===c.template)||templates[0],base=demo(t.id);const text=(v,n=500)=>String(v??'').slice(0,n);const image=v=>safeURL(v,'image').slice(0,900000);const out={...base};for(const k of ['name','tagline','description','about','phone','email','address','slug'])out[k]=text(c[k]??base[k],k==='about'?4000:1000);for(const k of ['website','instagram','telegram','whatsapp'])out[k]=safeURL(c[k]);for(const k of ['color','background','ink'])out[k]=/^#[a-f\d]{6}$/i.test(c[k])?c[k]:base[k];out.appName=text(c.appName,80).trim();out.appIcon=image(c.appIcon);out.lang=c.lang==='en'?'en':'fa';out.logo=image(c.logo);out.cover=image(c.cover);out.isDemo=!!c.isDemo;out.sections={...base.sections};for(const k of Object.keys(base.sections))if(typeof c.sections?.[k]==='boolean')out.sections[k]=c.sections[k];if(Array.isArray(c.items))out.items=c.items.slice(0,30).map((v,i)=>({id:/^[a-zA-Z0-9-]{1,50}$/.test(v.id)?v.id:String(i+1),title:text(v.title,150),description:text(v.description,3000),price:text(v.price,150),category:text(v.category,80),image:image(v.image),art:text(v.art,30)}));out.gallery=Array.isArray(c.gallery)?c.gallery.slice(0,12).map(image).filter(Boolean):[];for(const key of ['plans','reviews'])if(Array.isArray(c[key]))out[key]=c[key].slice(0,key==='reviews'?5:3).map(v=>Object.fromEntries((key==='plans'?['title','price','features']:['name','text']).map(k=>[k,text(v[k],1000)])));return out;}
